@layer components {
  :where([data-control-family="card"][data-slot="root"]) {
    --card-radius: var(--radius-lg);
    --card-background: var(--card);
    --card-border-color: var(--border);
    --card-border-width: 1px;
    --card-shadow: var(--shadow-sm);
    --card-backdrop-filter: none;
    border: var(--card-border-width) solid var(--card-border-color);
    border-radius: var(--card-radius);
    background: var(--card-background);
    color: var(--card-foreground);
    box-shadow: var(--card-shadow);
    -webkit-backdrop-filter: var(--card-backdrop-filter);
    backdrop-filter: var(--card-backdrop-filter);
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"]) {
    --card-shadow: var(--shadow-pop);
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"] > [data-slot="header"]) {
    border-block-end: 1px solid oklch(from var(--border) l c h / 0.7);
  }

  :where([data-control-family="card"][data-slot="title"]) {
    font-weight: 600;
    line-height: 1;
  }

  :where([data-control-family="card"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
  }

  :where([data-control-family="card"][data-slot="title"]) {
    line-height: 1;
  }
}

@property --card-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --card-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --card-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --card-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --card-shadow {
  syntax: "*";
  inherits: true;
  initial-value: none;
}

@property --card-backdrop-filter {
  syntax: "*";
  inherits: true;
  initial-value: none;
}

import type {
  CardActionProps,
  CardContentProps,
  CardDescriptionProps,
  CardFooterProps,
  CardHeaderProps,
  CardProps,
  CardTitleProps,
} from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function Card({ variant = "default", className, ...props }: CardProps) {
  return (
    <div
      data-control-ui="card"
      data-control-family="card"
      data-slot="root"
      data-surface="panel"
      data-variant={variant}
      className={cn(
        "flex flex-col gap-6 py-6",
        variant === "sectioned" &&
          "gap-0 py-0 [&>[data-slot=header]]:px-6 [&>[data-slot=header]]:py-5 [&>[data-slot=content]]:px-6 [&>[data-slot=content]]:py-6",
        className,
      )}
      {...props}
    />
  );
}

export function CardHeader({ className, ...props }: CardHeaderProps) {
  return (
    <div
      data-control-ui="card"
      data-control-family="card"
      data-slot="header"
      className={cn(
        "grid auto-rows-min grid-rows-[auto_auto] items-start gap-1.5 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
}

export function CardTitle({ className, ...props }: CardTitleProps) {
  return <div data-control-ui="card" data-control-family="card" data-slot="title" className={className} {...props} />;
}

export function CardDescription({ className, ...props }: CardDescriptionProps) {
  return <div data-control-ui="card" data-control-family="card" data-slot="description" className={className} {...props} />;
}

export function CardAction({ className, ...props }: CardActionProps) {
  return (
    <div
      data-control-ui="card"
      data-control-family="card"
      data-slot="action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
}

export function CardContent({ className, ...props }: CardContentProps) {
  return <div data-control-ui="card" data-control-family="card" data-slot="content" className={cn("px-6", className)} {...props} />;
}

export function CardFooter({ className, ...props }: CardFooterProps) {
  return (
    <div
      data-control-ui="card"
      data-control-family="card"
      data-slot="footer"
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      {...props}
    />
  );
}
